const state={user:null,csrf:'',categories:[],production:false,photoEnabled:false,photoRetentionDays:30,photoNoticeVersion:'',photoPage:1,photoStatus:'captured',page:'overview',preset:30,start:shift(today(),-29),end:today(),unit:'',data:null,extra:null,loading:false,error:'',search:'',sort:'score',sortDir:-1,evalPage:1,auditPage:1,alertStatus:'',compare:[],detailId:'',trendCategory:1,report:{category:'',minScore:'',maxScore:'',minVolume:'',alertStatus:''},updated:null};
let requestSequence=0,toastTimer,kioskTimer,successTimer,kiosk={step:'welcome',index:0,ratings:Array(6).fill(null),key:'',busy:false,error:'',remaining:7,lastActive:Date.now()};
async function api(path,options={}) {
  let response;
  try {response=await fetch(path,{credentials:'same-origin',...options,headers:{...options.body?{'Content-Type':'application/json','X-CSRF-Token':state.csrf}:{},...options.headers}});}
  catch(e){if(e.name==='AbortError')throw e;throw Error('Não foi possível conectar ao Vox. Verifique a conexão e tente novamente.');}
  if(!response.ok){const data=await response.json().catch(()=>({error:'Não foi possível conectar ao Vox.'}));if(response.status===401&&state.user){state.user=null;closeModal();renderLogin('Sua sessão expirou. Entre novamente.');}if(data.code==='PASSWORD_CHANGE_REQUIRED')passwordModal(true);throw Error(data.error||'Não foi possível concluir a operação.');}
  return response.json();
}
const post=(path,data={})=>api(path,{method:'POST',body:JSON.stringify(data)});
const patch=(path,data)=>api(path,{method:'PATCH',body:JSON.stringify(data)});
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
const empty=(title,message,i='bars')=>`<div class="empty">${icon(i)}<h3>${escape(title)}</h3><p>${escape(message)}</p></div>`;
const statusBadge=(s,kind='neutral')=>`<span class="badge ${kind}">${escape(s)}</span>`;
const scoreTone=v=>v==null?'neutral':v<state.data.settings.score_threshold-15?'critical':v<state.data.settings.score_threshold?'warning':'positive';
const scoreStatus=v=>v==null?'Sem dados':v<state.data.settings.score_threshold?'Atenção':'Bom desempenho';
function params({unit=state.page==='unit-detail'?state.detailId:state.unit,extra={}}={}){return new URLSearchParams({start:state.start,end:state.end,...unit?{unit}:{},...extra});}
async function init(){try{const me=await api('/api/me');Object.assign(state,{user:me.user,csrf:me.csrf,categories:me.categories,production:me.production,photoEnabled:me.photo_enabled,photoRetentionDays:me.photo_retention_days,photoNoticeVersion:me.photo_notice_version});if(state.user.role==='unit'){resetKiosk();return;}const hash=location.hash.slice(1);if(nav.some(x=>x[0]===hash))state.page=hash;await load();if(state.production&&state.user.must_change)passwordModal(true);}catch{renderLogin();}}
function renderLogin(error='') {
  resetPhoto();
  clearInterval(kioskTimer);clearTimeout(successTimer);
  $('#app').innerHTML=`<main id="main" class="login-page"><section class="login-story"><div class="login-brand">${brand()}</div><h1>A escuta que transforma o cuidado.</h1><p>Cada opinião ajuda a construir uma saúde melhor para Louveira.</p><div class="login-visual"><div class="login-visual-head">${icon('pulse')}Avaliação e inteligência em saúde</div><svg class="login-wave" viewBox="0 0 330 90" aria-hidden="true"><defs><linearGradient id="loginFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a4afff" stop-opacity=".13"/><stop offset="1" stop-color="#a4afff" stop-opacity="0"/></linearGradient></defs><path d="M0 70C25 70 28 50 48 53S75 66 95 48S125 60 145 36S178 44 195 24S225 47 245 20S285 25 307 9S320 15 330 10V90H0Z" fill="url(#loginFill)"/><path d="M0 70C25 70 28 50 48 53S75 66 95 48S125 60 145 36S178 44 195 24S225 47 245 20S285 25 307 9S320 15 330 10" class="chart-line"/></svg><small class="dim">Ouvir. Entender. Melhorar.</small></div><div class="login-story-footer">${icon('building')}Secretaria Municipal de Saúde de Louveira</div></section><section class="login-form-area"><form class="login-form" data-form="login"><h2>Bem-vindo ao Vox</h2><p>Acesse seu ambiente de gestão ou o totem de avaliação da sua unidade.</p><div class="field"><label for="username">Usuário</label><input id="username" name="username" placeholder="Digite seu usuário" autocomplete="username" required maxlength="60" autofocus></div><div class="field"><label for="password">Senha</label><div class="password-wrap"><input id="password" name="password" placeholder="Digite sua senha" type="password" autocomplete="current-password" required maxlength="128"><button type="button" class="icon-button" data-action="toggle-password" aria-label="Mostrar senha">${icon('eye')}</button></div></div><div id="login-error">${error?`<div class="error" role="alert">${escape(error)}</div>`:''}</div><button class="button primary" type="submit">Entrar no Vox ${icon('arrow')}</button><div class="login-help">Precisa de acesso?<br>Entre em contato com a administração da Secretaria de Saúde.</div><div class="login-legal">${icon('shield')}Ambiente de acesso restrito. As avaliações não solicitam nome, CPF ou informações de saúde do paciente.</div></form></section></main>`;
}
async function load(){
  if(!state.user||state.user.role!=='admin')return;
  const seq=++requestSequence;state.loading=true;state.error='';render();
  try {
    const query=params();const calls=[api('/api/admin/dashboard?'+query)];
    if(state.page==='evaluations'||state.page==='unit-detail')calls.push(api('/api/admin/evaluations?'+params({extra:{page:state.evalPage,...state.search?{q:state.search}:{}}})));
    else if(state.page==='photos')calls.push(api('/api/admin/photos?'+params({extra:{page:state.photoPage,...state.photoStatus?{status:state.photoStatus}:{}}})));
    else if(state.page==='users')calls.push(api('/api/admin/users'));
    else if(state.page==='alerts')calls.push(api('/api/admin/alerts?'+params({extra:state.alertStatus?{status:state.alertStatus}:{}})));
    else if(state.page==='reports')calls.push(api('/api/admin/alerts?'+params()));
    else if(state.page==='audit')calls.push(api('/api/admin/audit?'+params({extra:{page:state.auditPage}})));
    if(state.page==='unit-detail')calls.push(api('/api/admin/dashboard?'+params({unit:''})));
    const results=await Promise.all(calls);if(seq!==requestSequence)return;
    state.data=results[0];state.extra=results[1]||null;state.municipal=results[2]||null;state.updated=new Date();
    if(!state.compare.length)state.compare=state.data.units.filter(u=>u.count).slice(0,3).map(u=>u.id);
  }catch(e){if(seq!==requestSequence)return;state.error=e.message;}
  if(seq===requestSequence){state.loading=false;render();}
}
function navigate(page){state.page=page;state.search='';state.evalPage=1;state.auditPage=1;state.photoPage=1;state.extra=null;history.replaceState(null,'','#'+(page==='unit-detail'?'units':page));closeModal();load();window.scrollTo({top:0});}
function render(){
  if(!state.user)return;
  const active=state.page==='unit-detail'?'units':state.page,title=state.page==='unit-detail'?'Análise da unidade':nav.find(x=>x[0]===active)?.[1]||'Visão Geral';
  $('#app').innerHTML=`<div class="shell"><button class="drawer-backdrop" data-action="drawer" aria-label="Fechar navegação"></button><aside class="sidebar" aria-label="Navegação principal"><a class="brand" href="#overview" data-nav="overview"><div>${brand()}<div class="brand-caption">Inteligência em saúde</div></div></a><div class="workspace-label">${icon('building')}Secretaria de Saúde${icon('down')}</div><div class="nav-section">Gestão municipal</div><nav>${nav.filter(x=>!['users','settings'].includes(x[0])).map(([id,label,i])=>`<button class="nav-link ${active===id?'active':''}" data-nav="${id}" ${active===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='alerts'&&state.data?.alerts.length?`<span class="nav-count">${state.data.alerts.length}</span>`:''}</button>`).join('')}<div class="nav-divider"></div><div class="nav-section">Administração</div>${nav.filter(x=>['users','settings'].includes(x[0])).map(([id,label,i])=>`<button class="nav-link ${active===id?'active':''}" data-nav="${id}" ${active===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="municipality">${icon('shield')}<div><strong>Saúde de Louveira</strong><small>Ouvir para cuidar melhor.<br>Secretaria Municipal de Saúde</small></div></div><div class="sidebar-footer"><span>Vox v1.0</span><span><i></i>Ambiente local</span></div></div></aside><div class="main-area"><header class="topbar"><div class="breadcrumbs"><button class="icon-button mobile-menu" data-action="drawer" aria-label="Abrir navegação">${icon('menu')}</button>${icon('grid')}<span>Gestão municipal</span>${icon('chevron')}<span class="current">${escape(title)}</span></div><div class="topbar-right">${state.data?.demonstration?'<span class="environment">Dados de demonstração</span>':'<span class="environment">Ambiente de desenvolvimento</span>'}<button class="icon-button" data-nav="alerts" aria-label="Abrir alertas">${icon('bell')}</button><div class="topbar-divider"></div><button class="profile-button" data-action="profile" aria-label="Perfil e opções de acesso"><span class="avatar">DS</span><span><strong>Diretor de Saúde</strong><small>Administrador</small></span>${icon('down')}</button></div></header><main id="main" class="main-content" tabindex="-1"><div class="page-title"><div><h1>${escape(title)}</h1><p>${pageSubtitle()}</p></div><div class="page-title-actions">${pageActions()}</div></div>${filters()}${state.user.must_change?`<div class="info-strip">${icon('lock')}Sua conta utiliza uma senha provisória. Altere-a antes do uso em produção.<a href="#" data-action="password">Alterar senha</a></div>`:''}${state.error?`<div class="error" role="alert">${escape(state.error)} <button class="button small" data-action="refresh">Tentar novamente</button></div>`:''}${state.loading?'<div class="loading-section" role="status"><span class="spinner"></span>Atualizando os indicadores…</div>':state.data?renderPage():''}<footer class="dashboard-footer"><span>${icon('shield')}Vox · Secretaria Municipal de Saúde de Louveira</span><span>${state.updated?`Atualizado às ${state.updated.toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'})}`:''} · Fuso de São Paulo</span></footer></main></div></div>`;
}
function pageSubtitle(){return ({overview:'Uma visão integrada da experiência de quem utiliza a nossa rede de saúde.',units:'Gerencie a rede de saúde e acompanhe o desempenho de cada unidade.',photos:'Consulte os registros fotográficos autorizados, com acesso exclusivo da direção.',evaluations:'Consulte as opiniões recebidas, com transparência e rastreabilidade.',comparison:'Coloque os resultados lado a lado e identifique oportunidades de melhoria.',categories:'Os seis critérios que traduzem a experiência do paciente.',alerts:'Sinais que merecem atenção, com contexto para uma análise responsável.',audit:'Registro das operações e dos acessos ao ambiente Vox.',reports:'Transforme os resultados em relatórios para apoiar suas decisões.',users:'Controle os acessos da direção e os totens das unidades.',settings:'Defina os parâmetros de acompanhamento da rede.', 'unit-detail':'Entenda os resultados da unidade e as prioridades de melhoria.'})[state.page]||'';}
function pageActions(){
  if(state.page==='photos')return `<button class="button" data-action="refresh">${icon('refresh')}Atualizar</button>`;
  if(state.page==='units')return `<button class="button primary" data-action="new-unit">${icon('plus')}Nova unidade</button>`;
  if(state.page==='users')return `<button class="button primary" data-action="new-user">${icon('plus')}Criar acesso</button>`;
  if(state.page==='alerts')return `<button class="button" data-action="detect">${icon('refresh')}Verificar padrões</button>`;
  if(state.page==='reports')return `<button class="button" data-action="export" data-format="csv">${icon('download')}CSV</button><button class="button primary" data-action="export" data-format="pdf">${icon('file')}Exportar PDF</button>`;
  if(state.page==='unit-detail')return `<button class="button" data-nav="units">${icon('back')}Todas as unidades</button>`;
  return `<button class="button" data-action="refresh" aria-label="Atualizar indicadores">${icon('refresh')}Atualizar</button><button class="button primary" data-nav="reports">${icon('download')}Exportar relatório</button>`;
}
function filters(){return `<div class="filters"><div class="segmented" aria-label="Período de análise">${[[7,'7 dias'],[30,'30 dias'],[90,'90 dias'],[0,'Personalizado']].map(([v,label])=>`<button data-action="period" data-value="${v}" class="${state.preset===v?'selected':''}" ${state.preset===v?'aria-pressed="true"':'aria-pressed="false"'}>${label}</button>`).join('')}</div><div class="filter-controls"><button class="button" data-action="dates">${icon('calendar')}${date(state.start).slice(0,5)} – ${date(state.end).slice(0,5)}</button><div class="select-wrap">${icon('building')}<select id="unit-filter" aria-label="Filtrar por unidade"><option value="">Todas as unidades</option>${(state.data?.allUnits||[]).map(u=>`<option value="${u.id}" ${state.unit===u.id?'selected':''}>${escape(u.name)}</option>`).join('')}</select></div><button class="filter-reset" data-action="clear-filters">Limpar filtros</button></div></div>`;}
function renderPage(){return ({overview:overview,units:unitsPage,evaluations:evaluationsPage,photos:photosPage,comparison:comparisonPage,categories:categoriesPage,alerts:alertsPage,audit:auditPage,reports:reportsPage,users:usersPage,settings:settingsPage,'unit-detail':unitDetail})[state.page]?.()||'';}
function delta(current,old,unit='pts'){if(current==null||old==null||!state.data.previous.total)return '<span>Sem período anterior para comparar</span>';const d=unit==='%'?(old?(current-old)/old*100:0):current-old;return `<span class="delta ${d<0?'down':''}">${icon(d<0?'down':'up')}${d>0?'+':''}${n(d,1)} ${unit}</span><span>vs. período anterior</span>`;}
function kpis(){const d=state.data,s=d.summary,prev=d.previous;return `<section class="kpi-grid" aria-label="Indicadores principais"><article class="card kpi"><div class="kpi-label">${state.unit?'Score geral da unidade':'Score geral do município'}${icon('pulse')}</div><div class="kpi-value num">${n(s.score,1)}${s.score!=null?'<span class="suffix">/ 100</span>':''}</div><div class="kpi-foot">${delta(s.score,prev.score)}</div></article><article class="card kpi"><div class="kpi-label">Total de avaliações${icon('message')}</div><div class="kpi-value num">${n(s.total)}</div><div class="kpi-foot">${delta(s.total,prev.total,'%')}</div></article><article class="card kpi"><div class="kpi-label">UBS avaliadas${icon('building')}</div><div class="kpi-value num">${n(s.evaluated_units)}<span class="suffix">de ${d.allUnits.length} unidades</span></div><div class="kpi-foot">${icon('check')}Unidades com respostas no período</div></article><article class="card kpi"><div class="kpi-label">Satisfação geral${icon('heart')}</div><div class="kpi-value num">${n(s.satisfaction,2)}${s.satisfaction!=null?'<span class="suffix">/ 5</span>':''}</div><div class="kpi-foot">${s.satisfaction==null?'<span>Aguardando avaliações</span>':`${statusBadge(s.satisfaction>=4?'Experiência positiva':'Requer atenção',s.satisfaction>=4?'positive':'warning')}<span>${n(s.total)} respostas</span>`}</div></article></section>`;}
function compactTrend(trend,max=16){const size=Math.ceil(trend.length/max),result=[];for(let i=0;i<trend.length;i+=size){const group=trend.slice(i,i+size),count=group.reduce((sum,r)=>sum+r.count,0);result.push({day:group[0].day,end:group.at(-1).day,count,score:count?group.reduce((sum,r)=>sum+(r.score||0)*r.count,0)/count:null});}return result;}
function trendChart(trend){
  if(!trend.some(t=>t.count))return empty('A evolução começa com a primeira opinião','Selecione outro período ou receba avaliações pelo totem.');
  const rows=compactTrend(trend),w=650,h=195,l=36,r=12,t=15,b=29,threshold=state.data.settings.score_threshold,min=Math.max(0,Math.floor(Math.min(threshold,...rows.filter(r=>r.score!=null).map(r=>r.score))/20)*20-20),range=100-min;
  const x=i=>l+i/(Math.max(1,rows.length-1))*(w-l-r),y=v=>t+(100-v)/range*(h-t-b);
  let path='',has=false;for(const [i,row]of rows.entries()){if(row.score==null){has=false;continue;}path+=`${has?'L':'M'}${x(i).toFixed(2)} ${y(row.score).toFixed(2)} `;has=true;}
  const valid=rows.map((row,i)=>({...row,i})).filter(row=>row.score!=null),last=valid.at(-1);
  const grid=[0,1,2,3].map(i=>{const v=100-range/3*i;return `<line class="chart-grid" x1="${l}" y1="${y(v)}" x2="${w-r}" y2="${y(v)}"/><text class="chart-text" x="0" y="${y(v)+3}">${n(v)}</text>`;}).join('');
  return `<svg class="trend-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Evolução do score entre ${date(state.start)} e ${date(state.end)}. Média ponderada por volume em cada intervalo."><defs><linearGradient id="areaFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a4afff" stop-opacity=".15"/><stop offset="1" stop-color="#a4afff" stop-opacity="0"/></linearGradient></defs>${grid}<line x1="${l}" y1="${y(threshold)}" x2="${w-r}" y2="${y(threshold)}" class="chart-target"/>${valid.length===rows.length?`<path d="${path}L${x(last.i)} ${h-b} L${l} ${h-b}Z" fill="url(#areaFill)"/>`:''}<path d="${path}" class="chart-line"/>${valid.map(row=>`<circle cx="${x(row.i)}" cy="${y(row.score)}" r="${row.i===last.i?4:2.5}" class="chart-dot"><title>${date(row.day)}${row.end!==row.day?' a '+date(row.end):''}: ${n(row.score,1)}/100; ${row.count} avaliações</title></circle>`).join('')}${rows.filter((_,i)=>i===0||i===rows.length-1||i%Math.max(1,Math.floor(rows.length/5))===0).map(row=>{const i=rows.indexOf(row);return `<text class="chart-text" x="${x(i)}" y="${h-5}" text-anchor="${i===0?'start':i===rows.length-1?'end':'middle'}">${date(row.day).slice(0,5)}</text>`;}).join('')}</svg>`;
}
function trendCard(){return `<article class="card"><div class="card-header"><div><h2>Evolução do score geral</h2><p>A experiência do paciente ao longo do tempo</p></div><div class="chart-legend"><span class="legend-item"><i class="legend-dot"></i>Score geral</span><span class="legend-item"><i class="legend-dash"></i>Limite de atenção</span></div></div><div class="trend-summary num">${n(state.data.summary.score,1)}<small>pontos no período</small></div><div class="card-body">${trendChart(state.data.trend)}</div><div class="chart-note"><span>${icon('calendar')}${date(state.start)} a ${date(state.end)}</span><span>${n(state.data.summary.total)} avaliações</span></div></article>`;}
function categoryBars(categories=state.data.categories){return `<div class="category-bars">${categories.map(c=>`<div class="category-row"><span>${escape(c.name)}</span><div class="bar-track"><div class="bar-fill ${c.score==null?'':c.score<state.data.settings.score_threshold?'warning':''}" style="width:${c.score||0}%"></div></div><span class="value">${n(c.score,1)}</span></div>`).join('')}</div>`;}
function categoryCard(){return `<article class="card"><div class="card-header"><div><h2>Desempenho por categoria</h2><p>O que está funcionando e onde podemos melhorar</p></div><button class="card-link" data-nav="categories">Ver detalhes${icon('chevron')}</button></div><div class="card-body">${categoryBars()}</div><div class="chart-note"><span>Escala de 0 a 100 · pesos iguais</span><span>${n(state.data.summary.total)} avaliações</span></div></article>`;}
function volumeChart(){const rows=compactTrend(state.data.trend,20),max=Math.max(1,...rows.map(r=>r.count)),w=500,h=175,l=30,b=25,plot=w-l-10,bar=plot/rows.length;return `<svg class="volume-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Volume de avaliações por intervalo de datas, total ${state.data.summary.total}">${[0,.5,1].map(f=>`<line class="chart-grid" x1="${l}" x2="${w}" y1="${h-b-f*(h-b-10)}" y2="${h-b-f*(h-b-10)}"/><text class="chart-text" x="0" y="${h-b-f*(h-b-10)+3}">${n(max*f)}</text>`).join('')}${rows.map((r,i)=>`<rect class="volume-bar ${i===rows.length-1?'last':''}" x="${l+i*bar+bar*.2}" y="${h-b-r.count/max*(h-b-10)}" width="${bar*.6}" height="${r.count/max*(h-b-10)}" rx="3"><title>${date(r.day)} a ${date(r.end)}: ${r.count} avaliações</title></rect>${i===0||i===rows.length-1||i%Math.max(1,Math.floor(rows.length/4))===0?`<text x="${l+i*bar+bar*.5}" y="${h-3}" text-anchor="middle" class="chart-text">${date(r.day).slice(0,5)}</text>`:''}`).join('')}</svg>`;}
function volumeCard(){return `<article class="card"><div class="card-header"><div><h2>Volume de avaliações</h2><p>Participação dos pacientes no período selecionado</p></div>${icon('message')}</div><div class="card-body"><div class="volume-head"><strong class="num">${n(state.data.summary.total)}</strong><span>opiniões que fazem a diferença</span></div>${state.data.summary.total?volumeChart():empty('Nenhuma avaliação no período','Receba a primeira opinião pelo totem.')}</div></article>`;}
function attentionCard(){const units=state.data.units.filter(u=>u.count),best=units[0],worst=units.at(-1),p=state.data.priorities.slice(0,3);return `<article class="card attention-card"><div class="card-header"><div><h2>Um olhar sobre a rede</h2><p>Destaques e prioridades para sua gestão</p></div>${icon('spark')}</div>${best?`<div class="best-unit"><span class="best-unit-icon">${icon('trophy')}</span><div><div class="overline">Melhor desempenho</div><strong>${escape(best.name)}</strong></div><div class="best-score num">${n(best.score,1)}<small>${n(best.count)} avaliações${best.count<state.data.settings.sample_min?' · Amostra reduzida':''}</small></div></div>`:''}<div class="priority-list"><div class="priority-title"><span>Precisam de atenção</span>${p.length?statusBadge(p.length+' prioridades','warning'):''}</div>${p.length?p.map(row=>`<button class="priority" data-action="unit-detail" data-id="${row.unit_id}"><span class="priority-icon">${icon('alert')}</span><span><strong>${escape(row.unit_name)}</strong><small>${escape(row.category)}</small></span><span class="priority-score num">${n(row.score,1)}</span>${icon('chevron','priority-arrow')}</button>`).join(''):worst?`<button class="priority" data-action="unit-detail" data-id="${worst.id}"><span class="priority-icon">${icon('building')}</span><span><strong>${escape(worst.name)}</strong><small>Menor score da rede · ${n(worst.count)} avaliações</small></span><span class="priority-score num">${n(worst.score,1)}</span>${icon('chevron','priority-arrow')}</button><p class="help-text">Nenhuma categoria com amostra suficiente está abaixo do limite de atenção.</p>`:empty('Aguardando opiniões','Os destaques aparecem após as primeiras avaliações.','heart')}</div><div class="attention-footer">${icon('info')}Limite de atenção: ${state.data.settings.score_threshold} pontos · Amostra mínima: ${state.data.settings.sample_min}</div></article>`;}
function overview(){return `${state.data.demonstration?'<div class="info-strip">'+icon('info')+'Os registros fictícios estão identificados como demonstração. Nenhum resultado representa uma avaliação oficial.</div>':''}${kpis()}<section class="analytics-grid">${trendCard()}${attentionCard()}</section><section class="secondary-grid">${categoryCard()}${volumeCard()}</section>${unitTable(true)}`;}
function unitTable(ranking=false){const list=[...state.data.units].filter(u=>u.name.toLowerCase().includes(state.search.toLowerCase()));list.sort((a,b)=>{const k=state.sort;return k==='name'?a.name.localeCompare(b.name,'pt-BR')*state.sortDir:((a[k]??-1)-(b[k]??-1))*state.sortDir;});return `<section class="card"><div class="table-toolbar"><div><h2>${ranking?'Ranking das unidades':'Unidades da rede'}</h2><span class="subtitle">${ranking?'Resultados do período selecionado, calculados a partir das avaliações':'Cadastro, acesso e desempenho em um só lugar'}</span></div><label class="search-box">${icon('search')}<input type="search" data-input="unit-search" value="${escape(state.search)}" placeholder="Buscar unidade…" aria-label="Buscar unidade"></label></div><div class="table-wrap"><table class="data-table"><thead><tr>${ranking?'<th>Posição</th>':''}<th><button data-action="sort" data-value="name">Unidade de saúde${icon('sort')}</button></th><th><button data-action="sort" data-value="score">Score geral${icon('sort')}</button></th><th><button data-action="sort" data-value="count">Avaliações${icon('sort')}</button></th><th>Desempenho</th><th>${ranking?'Amostra':'Acesso'}</th><th class="right">Ações</th></tr></thead><tbody>${list.map((u,i)=>`<tr>${ranking?`<td><span class="rank">${String(i+1).padStart(2,'0')}</span></td>`:''}<td><button class="unit-cell" data-action="unit-detail" data-id="${u.id}"><span class="unit-symbol">${icon('building')}</span><span><strong>${escape(u.name)}</strong><small>${u.demo?'Cadastro de demonstração':u.code?'CNES '+escape(u.code):u.active?'Unidade ativa':'Unidade desativada'}</small></span></button></td><td><span class="score-cell num"><span class="tiny-bar"><i style="width:${u.score||0}%"></i></span>${n(u.score,1)}</span></td><td class="num">${n(u.count)}</td><td>${statusBadge(scoreStatus(u.score),scoreTone(u.score))}</td><td>${ranking?(u.count<state.data.settings.sample_min?statusBadge('Amostra reduzida','warning'):'<span class="dim">Amostra suficiente</span>'):(u.account_id?statusBadge(u.active&&u.account_active?'Ativo':'Desativado',u.active&&u.account_active?'positive':'neutral'):statusBadge('Sem acesso','neutral'))}</td><td class="right">${ranking?`<button class="button small ghost" data-action="unit-detail" data-id="${u.id}">Ver análise${icon('chevron')}</button>`:`<button class="icon-button" data-action="edit-unit" data-id="${u.id}" aria-label="Editar ${escape(u.name)}">${icon('edit')}</button><button class="button small ghost" data-action="toggle-unit" data-id="${u.id}">${u.active?'Desativar':'Ativar'}</button>`}</td></tr>`).join('')}</tbody></table>${!list.length?empty('Nenhuma unidade encontrada','Altere a busca ou cadastre uma nova unidade.','building'):''}</div><div class="table-footer"><span>${list.length} ${list.length===1?'unidade':'unidades'} · Score de 0 a 100</span><span>${ranking?'Amostras menores que '+state.data.settings.sample_min+' avaliações exigem cautela na comparação.':'A desativação preserva os registros históricos.'}</span></div></section>`;}
function unitsPage(){return unitTable(false);}
function evaluationsPage(){return evaluationTable();}
function evaluationTable(){const e=state.extra||{records:[],total:0,page:1,pages:0};return `<section class="card"><div class="table-toolbar"><div><h2>Avaliações recebidas</h2><span class="subtitle">${n(e.total)} registros no período</span></div>${state.page==='evaluations'?`<form data-form="evaluation-search" class="search-box">${icon('search')}<input name="q" value="${escape(state.search)}" placeholder="Unidade ou identificador…" aria-label="Buscar avaliações e pressionar Enter"></form>`:''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Avaliação</th><th>Unidade</th><th>Recebida em</th><th>Score</th><th>Registro fotográfico</th><th>Origem</th><th class="right">Ações</th></tr></thead><tbody>${e.records.map(r=>`<tr><td class="strong">#${r.id.slice(0,8).toUpperCase()}</td><td>${escape(r.unit_name)}</td><td class="num">${datetime(r.created_at)}</td><td class="num">${n(r.score,1)}</td><td>${statusBadge(photoLabel(r.photo_status),'neutral')}</td><td>${r.demo?'<span class="tag">Demonstração</span>':'<span class="muted">Totem</span>'}</td><td class="right"><button class="button small ghost" data-action="evaluation" data-id="${r.id}">Detalhes${icon('chevron')}</button></td></tr>`).join('')}</tbody></table>${!e.total?empty('Nenhuma avaliação neste período','Ajuste os filtros ou receba opiniões pelo totem.','message'):''}</div><div class="table-footer"><span>20 registros por página · notas sem nome ou CPF</span><div class="pagination"><button class="button ghost" data-action="eval-page" data-value="-1" ${e.page<=1?'disabled':''}>Anterior</button><span>${e.page} de ${Math.max(1,e.pages)}</span><button class="button ghost" data-action="eval-page" data-value="1" ${e.page>=e.pages?'disabled':''}>Próxima</button></div></div></section>`;}
const photoLabel=s=>({disabled:'Captura desativada',declined:'Foto recusada',camera_unavailable:'Câmera indisponível',permission_denied:'Permissão negada',capture_failed:'Falha na captura',captured:'Foto protegida',deleted:'Foto excluída'})[s]||'Sem registro';
function comparisonPage(){const units=state.data.units,selected=units.filter(u=>state.compare.includes(u.id));return `<div class="comparison-selection" role="group" aria-label="Selecionar unidades para comparar">${units.map(u=>`<label class="comparison-choice"><input type="checkbox" data-change="compare" value="${u.id}" ${state.compare.includes(u.id)?'checked':''}>${escape(u.name)}</label>`).join('')}</div>${selected.length>=2?`<section class="card"><div class="table-wrap"><table class="data-table comparison-table"><thead><tr><th>Indicador</th>${selected.map(u=>`<th>${escape(u.name)}</th>`).join('')}</tr></thead><tbody><tr><td>Score geral</td>${selected.map(u=>`<td class="big-score num">${n(u.score,1)}</td>`).join('')}</tr><tr><td>Avaliações no período</td>${selected.map(u=>`<td>${n(u.count)} ${u.count<state.data.settings.sample_min?statusBadge('Amostra reduzida','warning'):''}</td>`).join('')}</tr>${state.data.categories.map(c=>`<tr><td>${escape(c.name)}</td>${selected.map(u=>`<td><span class="score-cell num"><span class="tiny-bar"><i style="width:${u.categories[c.id-1].score||0}%"></i></span>${n(u.categories[c.id-1].score,1)}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`:empty('Selecione pelo menos duas unidades','Marque as unidades acima para comparar os seis critérios lado a lado.','compare')}<div class="rule-note"><strong>Compare também o tamanho da amostra.</strong> Todos os scores usam a mesma fórmula e os mesmos pesos. Resultados baseados em poucas opiniões exigem cautela. Período: ${date(state.start)} a ${date(state.end)}.</div>`;}
function categoriesPage(){const icons=['users','medical','clean','building','sign','heart'];return `<section class="category-overview">${state.data.categories.map((c,i)=>`<article class="card category-card"><div class="category-icon">${icon(icons[i])}</div><h2>${escape(c.name)}</h2><div class="category-value num">${n(c.score,1)} <small>${c.score==null?'':'/ 100'}</small></div><div class="bar-track"><div class="bar-fill ${c.score<state.data.settings.score_threshold?'warning':''}" style="width:${c.score||0}%"></div></div><p>${n(c.count)} avaliações · ${c.count<state.data.settings.sample_min?'Amostra reduzida':'Amostra suficiente'}</p><p>${c.score==null?'Sem dados no período.':`${n((c.score/25)+1,2)} / 5 na escala de avaliação`}</p></article>`).join('')}</section><div class="rule-note"><strong>Uma metodologia transparente.</strong> O score de cada categoria é (média das notas − 1) ÷ 4 × 100. Uma nota 1 vale 0 pontos; uma nota 5 vale 100. O score geral é a média das seis categorias, com pesos iguais.</div>`;}
function alertsPage(){const alerts=state.extra?.alerts||[];return `<div class="filters"><span class="help-text">${n(alerts.length)} alertas encontrados · Os sinais requerem análise e não comprovam irregularidade.</span><div class="select-wrap"><select id="alert-status" aria-label="Filtrar status dos alertas" style="padding-left:12px"><option value="">Todos os status</option>${['Novo','Em análise','Revisado','Encerrado'].map(s=>`<option ${state.alertStatus===s?'selected':''}>${s}</option>`).join('')}</select></div></div><section class="alert-list">${alerts.length?alerts.map(a=>`<article class="card alert-card ${a.severity}"><div class="alert-marker">${icon('alert')}</div><div class="alert-main"><h2>${escape(a.type)}${statusBadge(a.severity==='critical'?'Prioridade alta':'Atenção',a.severity==='critical'?'critical':'warning')}</h2><p>${escape(a.evidence)}</p><div class="alert-meta"><span>${escape(a.unit_name)}</span><span>${datetime(a.detected_at)}</span><span>${escape(a.status)}</span>${a.demo?'<span>Demonstração</span>':''}</div></div><div class="alert-actions"><button class="button small" data-action="alert" data-id="${a.id}">Revisar alerta${icon('chevron')}</button></div></article>`).join(''):empty('Nenhum alerta encontrado','Altere o período ou execute uma verificação dos padrões recentes.','shield')}</section>`;}
function auditPage(){const e=state.extra||{records:[],total:0,page:1},pages=Math.max(1,Math.ceil(e.total/30));return `<section class="card"><div class="table-toolbar"><div><h2>Trilha de auditoria</h2><span class="subtitle">${n(e.total)} eventos · registros preservados sem edição</span></div>${statusBadge('Acesso restrito','neutral')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Evento</th><th>Responsável</th><th>Data e hora</th><th>Referência</th><th>Contexto</th></tr></thead><tbody>${e.records.map(r=>`<tr><td><span class="audit-action">${icon('history')}${escape(r.action)}</span></td><td>${escape(r.username||'Sistema Vox')}</td><td class="num">${datetime(r.created_at)}</td><td>${escape(r.target.slice(0,12))}</td><td><button class="button small ghost" data-action="audit-detail" data-id="${r.id}">Ver contexto</button></td></tr>`).join('')}</tbody></table>${!e.total?empty('Nenhum evento no período','Os acessos e as operações administrativas aparecerão aqui.','history'):''}</div><div class="table-footer"><span>Os registros não contêm senhas ou tokens.</span><div class="pagination"><button class="button ghost" data-action="audit-page" data-value="-1" ${e.page<=1?'disabled':''}>Anterior</button><span>${e.page} de ${pages}</span><button class="button ghost" data-action="audit-page" data-value="1" ${e.page>=pages?'disabled':''}>Próxima</button></div></div></section>`;}
function reportUnits(){const f=state.report;return state.data.units.filter(u=>{const score=f.category?u.categories.find(c=>c.id===Number(f.category))?.score:u.score;return(score==null||((!f.minScore||score>=Number(f.minScore))&&(!f.maxScore||score<=Number(f.maxScore))))&&u.count>=Number(f.minVolume||0)&&(!f.alertStatus||(state.extra?.alerts||[]).some(a=>a.unit_id===u.id&&a.status===f.alertStatus));});}
function reportsPage(){const f=state.report,units=reportUnits();return `<section class="card report-controls"><div class="form-grid"><div class="field"><label for="report-category">Categoria</label><select id="report-category" data-report="category"><option value="">Score geral</option>${state.data.categories.map(c=>`<option value="${c.id}" ${String(c.id)===f.category?'selected':''}>${escape(c.name)}</option>`).join('')}</select></div><div class="field"><label for="report-min">Score mínimo / máximo</label><div style="display:flex;gap:8px"><input id="report-min" data-report="minScore" type="number" min="0" max="100" placeholder="0" value="${escape(f.minScore)}" aria-label="Score mínimo"><input data-report="maxScore" type="number" min="0" max="100" placeholder="100" value="${escape(f.maxScore)}" aria-label="Score máximo"></div></div><div class="field"><label for="report-volume">Mínimo de avaliações</label><input id="report-volume" data-report="minVolume" type="number" min="0" placeholder="Todas" value="${escape(f.minVolume)}"></div><div class="field"><label for="report-status">Status do alerta</label><select id="report-status" data-report="alertStatus"><option value="">Todos</option>${['Novo','Em análise','Revisado','Encerrado'].map(s=>`<option ${f.alertStatus===s?'selected':''}>${s}</option>`).join('')}</select></div></div></section><section class="card"><div class="table-toolbar"><div><h2>Prévia do relatório</h2><span class="subtitle">${units.length} unidades · ${date(state.start)} a ${date(state.end)}</span></div>${state.data.demonstration?'<span class="tag">Contém demonstração</span>':''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Unidade</th><th>Score geral</th><th>Avaliações</th><th>Principal ponto de melhoria</th></tr></thead><tbody>${units.map(u=>{const c=[...u.categories].filter(c=>c.score!=null).sort((a,b)=>a.score-b.score)[0];return `<tr><td class="strong">${escape(u.name)}</td><td class="num">${n(u.score,1)}</td><td class="num">${n(u.count)}</td><td>${escape(c?.name||'Sem dados')}</td></tr>`;}).join('')}</tbody></table>${!units.length?empty('Nenhuma unidade atende aos filtros','Altere os parâmetros para gerar o relatório.','file'):''}</div><div class="table-footer"><span>CSV e PDF incluem os seis critérios, metodologia, amostras e alertas.</span></div></section><div class="rule-note">${icon('shield')} Os relatórios são exclusivos da direção e não incluem fotografias, senhas, tokens ou informações pessoais de pacientes.</div>`;}
function usersPage(){const list=state.extra?.users||[];return `<section class="card"><div class="table-toolbar"><div><h2>Usuários e permissões</h2><span class="subtitle">Cada acesso de unidade está vinculado ao seu próprio totem.</span></div>${statusBadge('Permissões no servidor','positive')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Usuário</th><th>Perfil</th><th>Unidade vinculada</th><th>Status</th><th>Senha</th><th class="right">Ações</th></tr></thead><tbody>${list.map(u=>`<tr><td class="strong">${escape(u.username)}</td><td>${u.role==='admin'?'Diretor de Saúde':'Totem de avaliação'}</td><td>${escape(u.unit_name||'Gestão municipal')}</td><td>${statusBadge(u.active?'Ativo':'Desativado',u.active?'positive':'neutral')}</td><td>${u.must_change?statusBadge('Provisória','warning'):'<span class="dim">Atualizada</span>'}</td><td class="right">${u.id===state.user.id?'<button class="button small ghost" data-action="password">Alterar minha senha</button>':`<button class="button small ghost" data-action="reset-password" data-id="${u.id}">Redefinir senha</button> <button class="button small ghost" data-action="toggle-user" data-id="${u.id}">${u.active?'Desativar':'Ativar'}</button>`}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>O perfil da unidade permite apenas receber avaliações.</span><span>A redefinição de senha encerra as sessões existentes.</span></div></section>`;}
function settingsPage(){const cfg=state.data.settings,fields=[['score_threshold','Limite de atenção (0–100)',0,100,'Categorias abaixo deste score geram alertas.'],['sample_min','Amostra mínima',5,1000,'Quantidade mínima de avaliações para os alertas de desempenho.'],['repeat_threshold','Respostas idênticas em 10 minutos',3,50,'Sinaliza padrões repetidos na mesma unidade.'],['concentration_threshold','Envios por dispositivo em 10 minutos',5,100,'Sinaliza concentração de avaliações no totem.'],['decline_threshold','Queda do score entre semanas (pontos)',5,100,'Compara duas semanas com amostra suficiente.'],['volume_change_threshold','Variação de volume entre semanas (%)',25,1000,'Alerta para aumento ou redução relevante de participação.'],['high_threshold','Notas máximas em uma semana (%)',50,100,'Sinaliza concentração de avaliações com todas as notas 5.'],['photo_retention_days','Retenção de fotos (dias)',1,365,'Prazo máximo para novas fotos. A exclusão automática preserva as avaliações.']];return `<div class="settings-grid"><form class="card settings-form" data-form="settings"><h2>Parâmetros de acompanhamento</h2><p>As alterações ficam registradas na trilha de auditoria.</p><div class="form-grid">${fields.map(([key,label,min,max,help])=>`<div class="field"><label for="cfg-${key}">${label}</label><input id="cfg-${key}" name="${key}" type="number" min="${min}" max="${max}" value="${cfg[key]}" required><small>${help}</small></div>`).join('')}</div><div class="form-error"></div><div class="form-actions"><button class="button primary" type="submit">${icon('check')}Salvar parâmetros</button></div></form><div><article class="card privacy-card">${icon('shield')}<h2>Privacidade por padrão</h2>${statusBadge(state.photoEnabled?'Fotografias opcionais ativas':'Captura desativada',state.photoEnabled?'positive':'neutral')}<p style="margin-top:18px">A avaliação funciona integralmente sem fotografias. A câmera só é acionada após autorização do paciente.</p><p>Fotografias criptografadas, exclusivas da direção, com visualizações e exclusões registradas na auditoria. A publicação em produção depende da revisão formal da política de privacidade.</p><ul><li>Sem nome, CPF ou contato do paciente</li><li>Sem reconhecimento facial</li><li>Totem sem acesso aos resultados</li><li>Relatórios sem fotografias</li></ul></article><div class="rule-note"><strong>Metodologia fixa.</strong> As seis categorias têm pesos iguais. O Vox não altera pesos nem resultados históricos ao atualizar os limites de atenção.</div></div></div>`;}
function categoryEvolution(){const c=state.data.categories.find(c=>c.id===state.trendCategory),rows=state.data.trend.map(r=>{const v=state.data.category_trends.find(v=>v.day===r.day&&v.category_id===state.trendCategory);return{day:r.day,count:v?.count||0,score:v?.score??null};});return `<article class="card" style="margin-bottom:20px"><div class="card-header"><div><h2>Evolução por categoria</h2><p>${escape(c.name)} · scores calculados a partir das respostas do período</p></div><div class="select-wrap"><select id="category-trend" aria-label="Categoria do gráfico histórico" style="padding-left:12px;max-width:230px">${state.data.categories.map(c=>`<option value="${c.id}" ${c.id===state.trendCategory?'selected':''}>${escape(c.name)}</option>`).join('')}</select></div></div><div class="card-body">${trendChart(rows)}</div></article>`;}
function unitDetail(){const u=state.data.units[0];if(!u)return empty('Unidade não encontrada','Volte à lista de unidades.','building');const municipal=state.municipal,rank=municipal?.units.filter(u=>u.count).findIndex(x=>x.id===u.id)+1;const weakest=[...u.categories].filter(c=>c.score!=null).sort((a,b)=>a.score-b.score).slice(0,3);return `<div class="unit-detail-heading"><span class="unit-symbol">${icon('building')}</span><div><h2>${escape(u.name)}</h2><p>${escape(u.address||'Endereço não informado')} ${u.code?'· CNES '+escape(u.code):''}</p></div><span style="margin-left:auto">${statusBadge(u.active?'Ativa':'Desativada',u.active?'positive':'neutral')}</span></div><section class="kpi-grid"><article class="card kpi"><div class="kpi-label">Score da unidade${icon('pulse')}</div><div class="kpi-value num">${n(u.score,1)}<span class="suffix">/ 100</span></div><div class="kpi-foot">${delta(u.score,state.data.previous.score)}</div></article><article class="card kpi"><div class="kpi-label">Avaliações${icon('message')}</div><div class="kpi-value num">${n(u.count)}</div><div class="kpi-foot">${u.count<state.data.settings.sample_min?statusBadge('Amostra reduzida','warning'):'Amostra suficiente'}</div></article><article class="card kpi"><div class="kpi-label">Posição na rede${icon('trophy')}</div><div class="kpi-value num">${u.count?rank+'º':'—'}</div><div class="kpi-foot">Entre ${municipal?.summary.evaluated_units||0} unidades avaliadas</div></article><article class="card kpi"><div class="kpi-label">Média municipal${icon('building')}</div><div class="kpi-value num">${n(municipal?.summary.score,1)}<span class="suffix">/ 100</span></div><div class="kpi-foot">${u.score!=null&&municipal?.summary.score!=null?`${n(u.score-municipal.summary.score,1)} pontos em relação à rede`:'Sem dados para comparar'}</div></article></section><section class="analytics-grid">${trendCard()}<article class="card improvement-card"><h2>Principais pontos de melhoria</h2>${weakest.map((c,i)=>{const previous=state.data.previous_categories.find(x=>x.id===c.id),diff=previous?.score!=null?c.score-previous.score:null;return `<div class="improvement-item">${icon('alert')}<p><strong>${escape(c.name)}</strong>${i===0?' apresenta a menor pontuação da unidade no período.':` está entre as três menores pontuações.`}<br>${n(c.score,1)}/100 · ${c.count} avaliações<br><span class="dim">${diff==null||previous.count<state.data.settings.sample_min?'Sem amostra histórica suficiente para tendência.':Math.abs(diff)<1?'Estável em relação ao período anterior.':`${diff>0?'Melhora':'Queda'} de ${n(Math.abs(diff),1)} pontos no período equivalente anterior.`}</span></p></div>`;}).join('')||empty('Aguardando avaliações','As prioridades serão calculadas a partir dos resultados.')}<div class="help-text" style="margin-top:15px">Regra: ordenar os scores das categorias do menor para o maior.</div></article></section>${categoryEvolution()}<section class="secondary-grid">${categoryCard()}${volumeCard()}</section>${state.data.alerts.length?`<div class="info-strip">${icon('alert')}${state.data.alerts.length} alertas ativos associados a esta unidade.<a href="#" data-action="unit-alerts">Revisar alertas</a></div>`:''}${evaluationTable()}`;}

let previousFocus;
function modal(title,content,{locked=false}={}) {
  closeModal();previousFocus=document.activeElement;
  $('#modal-root').innerHTML=`<dialog aria-labelledby="modal-title" ${locked?'data-locked="true"':''}><div class="modal-header"><h2 id="modal-title">${escape(title)}</h2>${locked?'':`<button class="icon-button" data-action="close-modal" aria-label="Fechar">${icon('close')}</button>`}</div><div class="modal-body">${content}</div></dialog>`;
  const d=$('dialog');d.addEventListener('cancel',e=>{if(locked)e.preventDefault();else closeModal();});d.showModal();
}
let photoObjectUrl='',photoViewSequence=0;
function closeModal(){photoViewSequence++;if(photoObjectUrl){URL.revokeObjectURL(photoObjectUrl);photoObjectUrl='';}const d=$('dialog');if(d){d.close();$('#modal-root').innerHTML='';if(previousFocus?.isConnected)previousFocus.focus();}}
const formError=()=>'<div class="form-error" role="alert"></div>';
function datesModal(){modal('Escolher período',`<form data-form="dates"><p class="form-note">Todos os horários seguem o fuso de São Paulo.</p><div class="form-grid"><div class="field"><label for="date-start">Data inicial</label><input id="date-start" name="start" type="date" value="${state.start}" required></div><div class="field"><label for="date-end">Data final</label><input id="date-end" name="end" type="date" value="${state.end}" required></div></div>${formError()}<div class="form-actions"><button class="button ghost" type="button" data-action="close-modal">Cancelar</button><button class="button primary" type="submit">Aplicar período</button></div></form>`);}
function unitModal(id){const u=state.data.units.find(u=>u.id===id);modal(u?'Editar unidade':'Nova unidade de saúde',`<form data-form="unit" ${u?`data-id="${u.id}"`:''}><div class="field"><label for="unit-name">Nome da unidade</label><input id="unit-name" name="name" placeholder="Ex.: UBS Centro" value="${escape(u?.name||'')}" maxlength="150" required></div><div class="field"><label for="unit-address">Endereço</label><input id="unit-address" name="address" placeholder="Rua, número e bairro" value="${escape(u?.address||'')}" maxlength="250"></div><div class="field"><label for="unit-code">CNES (opcional)</label><input id="unit-code" name="code" placeholder="Identificação administrativa" value="${escape(u?.code||'')}" maxlength="30"></div>${u?`<div class="form-note">Dispositivo: <strong>${escape(u.device_id)}</strong> <button class="button small ghost" type="button" data-action="renew-device" data-id="${u.id}">Renovar identificador</button></div>`:`<div class="line"></div><h3>Acesso exclusivo do totem</h3><div class="form-grid"><div class="field"><label for="unit-username">Usuário da unidade</label><input id="unit-username" name="username" placeholder="UBSNomeDaUnidade" autocomplete="off" pattern="[A-Za-z][A-Za-z0-9]{2,59}" maxlength="60" required><small>UBS + nome sem espaços.</small></div><div class="field"><label for="unit-password">Senha provisória</label><input id="unit-password" name="password" type="password" autocomplete="new-password" minlength="10" maxlength="128" required><small>No mínimo 10 caracteres. Troca exigida em produção.</small></div></div>`}${formError()}<div class="form-actions"><button class="button ghost" data-action="close-modal" type="button">Cancelar</button><button class="button primary" type="submit">${u?'Salvar alterações':'Cadastrar unidade'}</button></div></form>`);}
function newUserModal(){const units=state.data.units.filter(u=>!u.account_id);modal('Criar acesso da unidade',units.length?`<form data-form="user"><p class="form-note">Este perfil permite somente receber avaliações na unidade vinculada.</p><div class="field"><label for="account-unit">Unidade</label><select name="unit_id" id="account-unit" required>${units.map(u=>`<option value="${u.id}">${escape(u.name)}</option>`).join('')}</select></div><div class="field"><label for="account-username">Usuário</label><input name="username" id="account-username" placeholder="UBSNomeDaUnidade" pattern="[A-Za-z][A-Za-z0-9]{2,59}" maxlength="60" required autocomplete="off"></div><div class="field"><label for="account-password">Senha provisória</label><input name="password" id="account-password" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></div>${formError()}<div class="form-actions"><button class="button primary" type="submit">Criar acesso</button></div></form>`:empty('Todas as unidades já possuem acesso','Cadastre uma nova unidade para criar outro acesso.','users'));}
function passwordModal(locked=false){modal('Alterar senha',`<form data-form="password"><p class="form-note">${locked?'Defina uma nova senha para concluir seu primeiro acesso.':'A alteração encerra outras sessões da sua conta.'}</p><div class="field"><label for="current-password">Senha atual</label><input id="current-password" name="current" type="password" autocomplete="current-password" required maxlength="128"></div><div class="field"><label for="next-password">Nova senha</label><input id="next-password" name="password" type="password" autocomplete="new-password" required minlength="10" maxlength="128"></div><div class="field"><label for="confirm-password">Confirmar nova senha</label><input id="confirm-password" name="confirm" type="password" autocomplete="new-password" required minlength="10" maxlength="128"></div>${formError()}<div class="form-actions"><button class="button primary" type="submit">Salvar nova senha</button></div></form>`,{locked});}
function resetPasswordModal(id){const u=state.extra.users.find(u=>u.id===id);modal('Redefinir senha de acesso',`<form data-form="reset-password" data-id="${id}"><p class="form-note">Defina a senha provisória de <strong>${escape(u.username)}</strong>. Todas as sessões desse acesso serão encerradas.</p><div class="field"><label for="reset-password">Nova senha provisória</label><input id="reset-password" name="password" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></div>${formError()}<div class="form-actions"><button class="button primary" type="submit">Redefinir senha</button></div></form>`);}
function evaluationModal(id){const r=state.extra.records.find(r=>r.id===id);modal('Detalhes da avaliação',`<div class="record-grid"><div><small>Unidade</small><strong>${escape(r.unit_name)}</strong></div><div><small>Recebida em</small><strong>${datetime(r.created_at)}</strong></div><div><small>Identificador</small><strong>${r.id}</strong></div><div><small>Dispositivo</small><strong>${escape(r.device_id)}</strong></div></div>${r.demo?'<div class="info-strip">'+icon('info')+'Registro fictício de demonstração.</div>':''}${r.ratings.map(x=>`<div class="record-rating"><span>${escape(state.categories[x.category_id-1].name)}</span><strong>${x.rating} / 5</strong></div>`).join('')}<div class="record-rating"><span>Score da avaliação</span><strong>${n(r.score,1)} / 100</strong></div><div class="rule-note">${icon('shield')} ${escape(photoLabel(r.photo_status))}. ${r.photo_status==='captured'&&r.evidence_id?`<button class="button" data-action="photo-view" data-id="${r.evidence_id}">${icon('camera')}Ver fotografia</button>`:'As notas foram preservadas independentemente da fotografia.'}</div>`);}
function alertModal(id){const a=state.extra.alerts.find(a=>a.id===id);modal('Revisar alerta',`<p><strong>${escape(a.type)}</strong><br>${escape(a.unit_name)}</p><p>${escape(a.evidence)}</p><form data-form="alert" data-id="${id}"><div class="field"><label for="review-status">Status da análise</label><select name="status" id="review-status">${['Novo','Em análise','Revisado','Encerrado'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="review-notes">Observações da direção</label><textarea name="notes" id="review-notes" maxlength="2000" placeholder="Registre o contexto e as providências tomadas.">${escape(a.notes)}</textarea></div>${formError()}<div class="form-actions"><button class="button primary" type="submit">Salvar revisão</button></div></form>${a.history.length?`<div class="line"></div><h3>Histórico da análise</h3>${a.history.map(h=>`<div class="history-item"><strong>${escape(h.status)}</strong> · ${datetime(h.created_at)} · ${escape(h.username||'Sistema')}<p>${escape(h.notes||'Sem observações adicionais.')}</p></div>`).join('')}`:''}`);}
function confirmModal(title,message,action,id){modal(title,`<p>${escape(message)}</p><div class="form-actions"><button class="button ghost" data-action="close-modal">Cancelar</button><button class="button primary" data-action="${action}" data-id="${id}">Confirmar</button></div>`);}
async function exportReport(format){const query=params({extra:{format,...state.report}});toast('Preparando o relatório…');const response=await fetch('/api/admin/reports?'+query,{credentials:'same-origin'});if(!response.ok){const r=await response.json();throw Error(r.error);}const blob=await response.blob(),link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=`vox-relatorio-${state.start}-${state.end}.${format}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Relatório exportado.');}

function photosPage(){
  const e=state.extra||{records:[],total:0,page:1,pages:0};
  return `<div class="info-strip">${icon('shield')}Fotografias opcionais e criptografadas. Cada visualização e exclusão é auditada. Retenção máxima de novas fotos: ${e.retention_days||state.photoRetentionDays} dias.</div><section class="card"><div class="table-toolbar"><div><h2>Registros fotográficos</h2><span class="subtitle">${n(e.total)} registros no período</span></div><div class="field"><label for="photo-status">Status da fotografia</label><select id="photo-status">${[['','Todos os registros'],['captured','Fotos disponíveis'],['declined','Foto recusada'],['camera_unavailable','Câmera indisponível'],['permission_denied','Permissão negada'],['capture_failed','Falha na captura'],['deleted','Fotos excluídas']].map(([v,label])=>`<option value="${v}" ${state.photoStatus===v?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Avaliação</th><th>Unidade</th><th>Recebida em</th><th>Status</th><th>Exclusão prevista</th><th class="right">Ações</th></tr></thead><tbody>${e.records.map(r=>`<tr><td class="strong">#${r.evaluation_id.slice(0,8).toUpperCase()}</td><td>${escape(r.unit_name)}</td><td>${datetime(r.created_at)}</td><td>${statusBadge(photoLabel(r.status),r.status==='captured'?'positive':'neutral')}</td><td>${r.status==='captured'&&r.expires_at?datetime(r.expires_at):'—'}</td><td class="right">${r.status==='captured'?`<button class="button small" data-action="photo-view" data-id="${r.id}">${icon('eye')}Ver foto</button>`:'—'}</td></tr>`).join('')}</tbody></table>${!e.total?empty('Nenhuma fotografia neste período','Fotos autorizadas no totem aparecerão aqui. Ajuste os filtros para consultar outros registros.','camera'):''}</div><div class="table-footer"><span>As fotografias não são incluídas nos relatórios.</span><div class="pagination"><button class="button ghost" data-action="photo-page" data-value="-1" ${e.page<=1?'disabled':''}>Anterior</button><span>${e.page} de ${Math.max(1,e.pages)}</span><button class="button ghost" data-action="photo-page" data-value="1" ${e.page>=e.pages?'disabled':''}>Próxima</button></div></div></section>`;
}
async function viewPhoto(id){
  closeModal();const sequence=photoViewSequence;toast('Abrindo fotografia protegida…');
  const response=await fetch('/api/admin/photos/'+encodeURIComponent(id)+'/image',{credentials:'same-origin',cache:'no-store'});
  if(!response.ok){if(response.status===401){state.user=null;renderLogin('Sua sessão expirou. Entre novamente.');}throw Error((await response.json()).error);}
  const blob=await response.blob();if(sequence!==photoViewSequence||state.user?.role!=='admin')return;
  modal('Fotografia da avaliação',`<p class="form-note">Acesso exclusivo da direção. Esta visualização foi registrada na auditoria.</p><img class="director-photo" alt="Fotografia autorizada pelo paciente"><div class="form-actions"><button class="button danger" data-action="photo-delete" data-id="${escape(id)}">Excluir fotografia</button><button class="button" data-action="close-modal">Fechar</button></div>`);
  photoObjectUrl=URL.createObjectURL(blob);$('.director-photo').src=photoObjectUrl;
}

let camera={status:'pending',data:'',stream:null,message:'',generation:0,noticeVersion:'',retentionDays:30};
function stopCamera(){camera.generation++;if(camera.stream){for(const track of camera.stream.getTracks())track.stop();camera.stream=null;}const video=$('#camera-preview');if(video)video.srcObject=null;}
function resetPhoto(status='pending'){stopCamera();camera.status=status;camera.data='';camera.message='';camera.noticeVersion='';camera.retentionDays=state.photoRetentionDays;}
function photoReview(){
  const disabled=kiosk.busy?'disabled':'';
  const notice=`<div class="privacy-notice photo-consent">${icon('shield')}<div><h2>Registro fotográfico da avaliação</h2><p>Com sua autorização, uma foto será registrada como apoio à verificação da integridade das avaliações pela direção. Ela ficará criptografada, com acesso exclusivo do diretor, por até <strong>${state.photoRetentionDays} dias</strong>, e será excluída automaticamente.</p><p>A fotografia é opcional. Você pode escolher <strong>CONTINUAR SEM FOTO</strong> e enviar sua avaliação normalmente. Não usamos reconhecimento facial. Ao tocar em <strong>AUTORIZAR FOTO</strong>, você concorda com esse registro e seu prazo de retenção.</p></div></div>`;
  if(camera.status==='pending')return `${notice}<div class="photo-actions"><button class="button primary big-button" data-action="camera-authorize" ${disabled}>${icon('camera')}AUTORIZAR FOTO</button><button class="button big-button" data-action="camera-decline" ${disabled}>CONTINUAR SEM FOTO</button></div>`;
  if(camera.status==='opening'||camera.status==='preview')return `${notice}<div class="camera-frame"><video id="camera-preview" autoplay muted playsinline aria-label="Prévia da câmera"></video></div><p class="help-text">${camera.status==='opening'?'Autorize o acesso à câmera quando o navegador solicitar.':'Confira o enquadramento e toque em TIRAR FOTO.'}</p><div class="photo-actions"><button class="button primary big-button" data-action="camera-capture" ${camera.status==='opening'?'disabled':''}>${icon('camera')}TIRAR FOTO</button><button class="button big-button" data-action="camera-decline">CONTINUAR SEM FOTO</button></div>`;
  if(camera.data)return `<div class="camera-frame"><img src="${camera.data}" alt="Prévia da fotografia, ainda não enviada"></div><p class="help-text">Foto pronta. Ela só será salva quando você enviar a avaliação. Retenção: até ${camera.retentionDays} dias.</p><div class="photo-actions"><button class="button" data-action="camera-authorize" ${disabled}>${icon('refresh')}TIRAR OUTRA FOTO</button><button class="button" data-action="camera-decline" ${disabled}>REMOVER FOTO</button></div>`;
  return `<div class="privacy-notice">${icon('shield')}<p><strong>${camera.status==='declined'?'Você escolheu continuar sem foto.':escape(camera.message||'Não foi possível tirar a foto.')}</strong><br>Suas seis respostas podem ser enviadas normalmente.</p></div><div class="photo-actions"><button class="button" data-action="camera-authorize" ${disabled}>${icon('camera')}${camera.status==='declined'?'AUTORIZAR FOTO':'TENTAR CÂMERA NOVAMENTE'}</button></div>`;
}
async function authorizeCamera(){
  if(kiosk.busy||kiosk.step!=='review'||!state.photoEnabled)return;
  resetPhoto();camera.noticeVersion=state.photoNoticeVersion;camera.retentionDays=state.photoRetentionDays;
  if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia){camera.status='camera_unavailable';camera.message='A câmera precisa de um navegador compatível e de uma conexão HTTPS ou localhost.';renderKiosk();return;}
  camera.status='opening';const generation=camera.generation;renderKiosk();
  try {
    const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});
    if(generation!==camera.generation||kiosk.step!=='review'||state.user?.role!=='unit'||document.hidden){stream.getTracks().forEach(track=>track.stop());return;}
    camera.stream=stream;camera.status='preview';renderKiosk();const video=$('#camera-preview');video.srcObject=stream;
    await video.play();
  }catch(error){
    if(generation!==camera.generation)return;stopCamera();
    camera.status=error.name==='NotAllowedError'||error.name==='SecurityError'?'permission_denied':'camera_unavailable';
    camera.message=camera.status==='permission_denied'?'O acesso à câmera foi negado. Você pode liberá-lo nas permissões do navegador.':'A câmera está indisponível ou em uso por outro aplicativo.';renderKiosk();
  }
}
function captureCamera(){
  if(kiosk.busy||camera.status!=='preview')return;
  try{const video=$('#camera-preview');if(!video?.videoWidth)throw Error('Aguarde a câmera ficar pronta e tente novamente.');const ratio=Math.min(640/video.videoWidth,480/video.videoHeight,1),canvas=document.createElement('canvas');canvas.width=Math.round(video.videoWidth*ratio);canvas.height=Math.round(video.videoHeight*ratio);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);camera.data=canvas.toDataURL('image/jpeg',0.8);camera.status='captured';stopCamera();renderKiosk();}
  catch(error){stopCamera();camera.status='capture_failed';camera.data='';camera.message=error.message||'Não foi possível tirar a foto.';renderKiosk();}
}
function staffModal(){modal('Acesso da equipe',`<form data-form="staff"><p class="form-note">Informe a senha da unidade para acessar as opções do totem.</p><div class="field"><label for="staff-password">Senha da unidade</label><input id="staff-password" name="password" type="password" autocomplete="current-password" required maxlength="128"></div>${formError()}<div class="form-actions"><button class="button primary" type="submit">Continuar</button></div></form>`);}
function unitLogoutModal(){
  if(kiosk.busy)return;
  if(camera.stream||camera.status==='opening'){resetPhoto();renderKiosk();}
  modal('Sair da unidade',`<form data-form="unit-logout"><p class="form-note">Para encerrar o acesso de <strong>${escape(state.user.unit_name)}</strong> e voltar ao login, informe a senha da unidade.</p><div class="field"><label for="logout-password">Senha da unidade</label><input id="logout-password" name="password" type="password" autocomplete="current-password" required maxlength="128"></div>${formError()}<div class="form-actions"><button class="button ghost" type="button" data-action="close-modal">Cancelar</button><button class="button danger" type="submit">${icon('logout')}Sair</button></div></form>`);
}
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(camera.stream||camera.status==='opening'){resetPhoto();if(state.user?.role==='unit')renderKiosk();}closeModal();}});
window.addEventListener('pagehide',()=>{resetPhoto();closeModal();});

// Accessible, unit-bound evaluation kiosk.
function face(score){const mouth=score===1?'M15 35Q25 22 35 35':score===2?'M16 33Q25 25 34 33':score===3?'M17 32h16':score===4?'M16 30Q25 40 34 30':'M15 28Q25 44 35 28Z';return `<svg class="face" viewBox="0 0 50 50" aria-hidden="true"><circle cx="25" cy="25" r="21"/><path d="M17 19h.2 M33 19h.2 ${mouth}"/></svg>`;}
const ratingNames=['Muito ruim','Ruim','Regular','Bom','Excelente'];
function resetKiosk(){resetPhoto();closeModal();clearTimeout(successTimer);clearInterval(kioskTimer);kiosk={step:'welcome',index:0,ratings:Array(6).fill(null),key:'',busy:false,error:'',remaining:7,lastActive:Date.now()};renderKiosk();kioskTimer=setInterval(kioskTick,1000);if(state.production&&state.user.must_change)passwordModal(true);}
function kioskTick(){if(!state.user||state.user.role!=='unit')return;const idle=Date.now()-kiosk.lastActive;if(kiosk.step==='success'){kiosk.remaining--;const c=$('#reset-countdown');if(c)c.textContent=kiosk.remaining;return;}if(kiosk.busy)return;if(idle>=120000&&$('dialog')){closeModal();resetKiosk();return;}if(kiosk.step==='welcome')return;if(idle>=120000){closeModal();resetKiosk();return;}const warning=$('#inactivity-warning');if(idle>=90000&&!warning){const div=document.createElement('div');div.id='inactivity-warning';div.className='inactivity-warning';div.setAttribute('role','alert');div.innerHTML=`A avaliação será reiniciada por inatividade.<button class="button" data-action="kiosk-continue">Continuar avaliando</button>`;$('.kiosk').append(div);}else if(idle<90000&&warning)warning.remove();}
function renderKiosk(){
  let content='';
  if(kiosk.step==='welcome')content=`<div class="kiosk-welcome-icon">${icon('message')}</div><h1>Como foi seu atendimento hoje?</h1><p>Sua opinião nos ajuda a cuidar melhor de você.<br>São apenas seis perguntas.</p><button class="button primary big-button" data-action="kiosk-start">AVALIAR ATENDIMENTO${icon('arrow')}</button><p class="help-text" style="margin:24px 0 0;font-size:14px">Você não precisa informar seu nome ou seus dados pessoais.</p>`;
  if(kiosk.step==='questions')content=`<div class="kiosk-progress" aria-label="Progresso: pergunta ${kiosk.index+1} de 6"><i style="width:${(kiosk.index+1)/6*100}%"></i></div><div class="kiosk-question-count">Pergunta ${kiosk.index+1} de 6</div><h1 id="question-heading">${escape(state.categories[kiosk.index].question)}</h1><div class="rating-options" role="group" aria-labelledby="question-heading">${ratingNames.map((name,i)=>`<button class="rating-option ${kiosk.ratings[kiosk.index]===i+1?'chosen':''}" data-action="rating" data-value="${i+1}" aria-pressed="${kiosk.ratings[kiosk.index]===i+1}">${face(i+1)}<strong>${i+1}</strong><small>${name}</small></button>`).join('')}</div><div class="kiosk-validation" role="status">${kiosk.ratings[kiosk.index]==null?'Escolha uma opção para continuar.':'Resposta selecionada. Você pode alterá-la.'}</div><div class="kiosk-actions"><button class="button ghost big-button" data-action="kiosk-back">${icon('back')}VOLTAR</button><button class="button primary big-button" data-action="kiosk-next" ${kiosk.ratings[kiosk.index]==null?'disabled':''}>${kiosk.index===5?'REVISAR':'PRÓXIMA'}${icon('arrow')}</button></div>`;
  if(kiosk.step==='review')content=`<div class="kiosk-question-count">Último passo</div><h1>Confira suas respostas</h1><p>Toque na nota se quiser mudar alguma resposta.</p><div class="kiosk-review">${state.categories.map((c,i)=>`<div class="kiosk-review-row"><span>${escape(c.name)}</span><button data-action="kiosk-edit" data-value="${i}" aria-label="Alterar resposta de ${escape(c.name)}">${kiosk.ratings[i]} · ${ratingNames[kiosk.ratings[i]-1]} ${icon('edit')}</button></div>`).join('')}</div>${state.photoEnabled?photoReview():`<div class="privacy-notice">${icon('shield')}<p>A captura de fotos está desativada. Envie sua avaliação normalmente.</p></div>`}${kiosk.error?`<div class="error" role="alert">${escape(kiosk.error)}<br>Suas respostas continuam aqui. Tente enviar novamente.</div>`:''}<div class="kiosk-actions"><button class="button ghost big-button" data-action="kiosk-back" ${kiosk.busy?'disabled':''}>${icon('back')}VOLTAR</button><button class="button primary big-button" data-action="kiosk-submit" ${kiosk.busy||state.photoEnabled&&['pending','opening','preview'].includes(camera.status)?'disabled':''}>${kiosk.busy?'<span class="spinner"></span>ENVIANDO…':`${kiosk.error?'TENTAR NOVAMENTE':'ENVIAR AVALIAÇÃO'}${icon('check')}`}</button></div>`;
  if(kiosk.step==='success')content=`<div class="success-icon">${icon('check')}</div><h1>Obrigado por avaliar nosso atendimento!</h1><p>Sua opinião contribui para a melhoria dos serviços de saúde de Louveira.</p><div class="badge positive" style="font-size:16px;padding:10px 15px">Avaliação recebida com sucesso</div>${state.photoEnabled?`<p class="help-text">${kiosk.photoSaved?'Sua fotografia autorizada foi recebida.':'Sua avaliação foi salva sem fotografia.'}</p>`:''}<p class="help-text" style="margin:25px 0 0;font-size:14px">A tela inicial voltará em <span id="reset-countdown">${kiosk.remaining}</span> segundos.</p>`;
  $('#app').innerHTML=`<div class="kiosk"><header class="kiosk-header">${brand()}<div class="kiosk-access"><div class="kiosk-unit">${icon('building')}${escape(state.user.unit_name)}</div><button class="button kiosk-logout" data-action="unit-logout" ${kiosk.busy?'disabled':''}>${icon('logout')}Sair</button></div></header><main id="main" class="kiosk-main" tabindex="-1">${content}</main><footer class="kiosk-footer"><span>Secretaria Municipal de Saúde de Louveira · Vox</span><button class="icon-button" data-action="staff" aria-label="Acesso da equipe">${icon('lock')}</button></footer></div>`;
}
async function submitEvaluation(){if(kiosk.busy||kiosk.ratings.some(x=>x===null)||state.photoEnabled&&['pending','opening','preview'].includes(camera.status))return;stopCamera();kiosk.busy=true;kiosk.error='';renderKiosk();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await api('/api/evaluations',{method:'POST',body:JSON.stringify({ratings:kiosk.ratings,key:kiosk.key,photo_status:state.photoEnabled?camera.status:'disabled',...(camera.data?{photo:{data:camera.data,consent:true,notice_version:camera.noticeVersion,retention_days:camera.retentionDays}}:{})}),signal:controller.signal});if(r.saved!==true)throw Error('O servidor ainda não confirmou o recebimento.');kiosk.photoSaved=r.photo_status==='captured';resetPhoto();kiosk.ratings=Array(6).fill(null);kiosk.key='';kiosk.step='success';kiosk.remaining=7;renderKiosk();successTimer=setTimeout(resetKiosk,7000);}catch(e){if(!state.user)return;kiosk.error=e.name==='AbortError'?'A conexão demorou mais que o esperado.':e.message;kiosk.busy=false;renderKiosk();post('/api/technical',{code:'SUBMISSION_FAILURE'}).catch(()=>{});}finally{clearTimeout(timer);}}
async function logout(){await post('/api/auth/logout');state.user=null;state.data=null;state.extra=null;closeModal();clearInterval(kioskTimer);clearTimeout(successTimer);history.replaceState(null,'',location.pathname);renderLogin();}

document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-nav],[data-action]');if(!target)return;event.preventDefault();
  if(target.disabled)return;
  if(target.dataset.nav){if(state.user?.role==='admin')navigate(target.dataset.nav);return;}
  const action=target.dataset.action,id=target.dataset.id,value=target.dataset.value;
  try {
    if(action==='camera-authorize')await authorizeCamera();
    else if(action==='camera-capture')captureCamera();
    else if(action==='camera-decline'){resetPhoto('declined');renderKiosk();}
    else if(action==='photo-view')await viewPhoto(id);
    else if(action==='photo-page'){state.photoPage+=Number(value);await load();}
    else if(action==='photo-delete')confirmModal('Excluir fotografia','A fotografia será excluída. As seis notas da avaliação serão preservadas.','photo-delete-confirm',id);
    else if(action==='photo-delete-confirm'){await api('/api/admin/photos/'+id,{method:'DELETE',headers:{'X-CSRF-Token':state.csrf}});closeModal();toast('Fotografia excluída. Avaliação preservada.');await load();}
    else if(action==='close-modal')closeModal();
    else if(action==='drawer')$('.shell')?.classList.toggle('drawer-open');
    else if(action==='toggle-password'){const i=$('#password');i.type=i.type==='password'?'text':'password';target.setAttribute('aria-label',i.type==='password'?'Mostrar senha':'Ocultar senha');}
    else if(action==='refresh')await load();
    else if(action==='period'){if(Number(value)===0)datesModal();else{state.preset=Number(value);state.end=today();state.start=shift(state.end,1-state.preset);state.evalPage=1;state.auditPage=1;await load();}}
    else if(action==='dates')datesModal();
    else if(action==='clear-filters'){Object.assign(state,{preset:30,start:shift(today(),-29),end:today(),unit:'',evalPage:1,auditPage:1,report:{category:'',minScore:'',maxScore:'',minVolume:'',alertStatus:''}});if(state.page==='unit-detail')state.page='units';await load();}
    else if(action==='profile')modal('Seu acesso',`<p>Conectado como <strong>${escape(state.user.username)}</strong><br>Diretor de Saúde · Administrador</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="button" data-action="password">${icon('lock')}Alterar senha</button><button class="button danger" data-action="logout">${icon('logout')}Sair do Vox</button></div>`);
    else if(action==='password')passwordModal();
    else if(action==='logout')await logout();
    else if(action==='unit-logout')unitLogoutModal();
    else if(action==='new-unit')unitModal();
    else if(action==='edit-unit')unitModal(id);
    else if(action==='sort'){state.sortDir=state.sort===value?-state.sortDir:value==='name'?1:-1;state.sort=value;render();}
    else if(action==='unit-detail'){state.detailId=id;state.evalPage=1;navigate('unit-detail');}
    else if(action==='toggle-unit'){const u=state.data.units.find(u=>u.id===id);confirmModal(u.active?'Desativar unidade':'Ativar unidade',u.active?'O totem desta unidade deixará de receber avaliações. Os registros históricos serão preservados.':'O totem da unidade voltará a aceitar avaliações se seu acesso estiver ativo.','confirm-unit',id);}
    else if(action==='confirm-unit'){const u=state.data.units.find(u=>u.id===id);await patch('/api/admin/units/'+id,{active:!u.active});closeModal();toast('Status da unidade atualizado.');await load();}
    else if(action==='renew-device'){await patch('/api/admin/units/'+id+'/device',{});closeModal();toast('Novo identificador de dispositivo gerado.');await load();}
    else if(action==='new-user')newUserModal();
    else if(action==='reset-password')resetPasswordModal(id);
    else if(action==='toggle-user'){const u=state.extra.users.find(u=>u.id===id);confirmModal(u.active?'Desativar acesso':'Ativar acesso',u.active?'Este usuário deixará de acessar o Vox. As sessões existentes serão encerradas.':'Este usuário voltará a acessar seu ambiente.','confirm-user',id);}
    else if(action==='confirm-user'){const u=state.extra.users.find(u=>u.id===id);await patch('/api/admin/users/'+id,{active:!u.active});closeModal();toast('Acesso atualizado.');await load();}
    else if(action==='evaluation')evaluationModal(id);
    else if(action==='eval-page'){state.evalPage+=Number(value);await load();}
    else if(action==='audit-page'){state.auditPage+=Number(value);await load();}
    else if(action==='alert')alertModal(id);
    else if(action==='detect'){target.disabled=true;await post('/api/admin/alerts/detect');toast('Verificação concluída.');await load();}
    else if(action==='unit-alerts'){state.unit=state.detailId;navigate('alerts');}
    else if(action==='audit-detail'){const r=state.extra.records.find(r=>r.id===id);const m=JSON.parse(r.metadata);modal('Contexto do evento',`<p><strong>${escape(r.action)}</strong><br>${datetime(r.created_at)} · ${escape(r.username||'Sistema Vox')}</p><div class="record-grid">${Object.entries(m).map(([k,v])=>`<div><small>${escape(({unit_id:'Unidade',device:'Dispositivo',code:'Código',start:'Data inicial',end:'Data final',status:'Status',demo:'Demonstração',name:'Nome',username:'Usuário',active:'Ativo',type:'Tipo',evidence:'Contexto',units:'Unidades',score_threshold:'Limite de atenção',sample_min:'Amostra mínima',repeat_threshold:'Padrões repetidos',concentration_threshold:'Concentração de envios',decline_threshold:'Queda de score',volume_change_threshold:'Variação de volume',high_threshold:'Concentração de notas máximas',photo_retention_days:'Retenção proposta (dias)'})[k]||k)}</small><strong>${escape(typeof v==='object'?JSON.stringify(v):v)}</strong></div>`).join('')||'<p>Sem contexto adicional.</p>'}</div>`);}
    else if(action==='export')await exportReport(target.dataset.format);
    else if(action==='kiosk-start'){resetPhoto();kiosk.step='questions';kiosk.index=0;kiosk.ratings=Array(6).fill(null);kiosk.key=crypto.randomUUID();renderKiosk();}
    else if(action==='rating'){kiosk.ratings[kiosk.index]=Number(value);renderKiosk();const chosen=$(`.rating-option[data-value="${value}"]`);chosen?.focus();}
    else if(action==='kiosk-next'){if(kiosk.ratings[kiosk.index]===null)return;if(kiosk.index<5)kiosk.index++;else kiosk.step='review';renderKiosk();$('#main').focus();}
    else if(action==='kiosk-back'){stopCamera();if(!camera.data)resetPhoto();if(kiosk.step==='review'){kiosk.step='questions';kiosk.index=5;}else if(kiosk.index>0)kiosk.index--;else kiosk.step='welcome';renderKiosk();$('#main').focus();}
    else if(action==='kiosk-edit'){stopCamera();if(!camera.data)resetPhoto();kiosk.index=Number(value);kiosk.step='questions';renderKiosk();}
    else if(action==='kiosk-submit')await submitEvaluation();
    else if(action==='kiosk-continue'){kiosk.lastActive=Date.now();$('#inactivity-warning')?.remove();}
    else if(action==='staff'){if(camera.stream||camera.status==='opening'){resetPhoto();renderKiosk();}staffModal();}
  }catch(e){toast(e.message);if(target.isConnected)target.disabled=false;}
});
document.addEventListener('change',event=>{
  const t=event.target;
  if(t.id==='photo-status'){state.photoStatus=t.value;state.photoPage=1;load();}
  else if(t.id==='unit-filter'){state.unit=t.value;state.evalPage=1;state.auditPage=1;if(state.page==='unit-detail')state.page='units';load();}
  else if(t.dataset.change==='compare'){state.compare=t.checked?[...new Set([...state.compare,t.value])]:state.compare.filter(v=>v!==t.value);render();}
  else if(t.id==='alert-status'){state.alertStatus=t.value;load();}
  else if(t.id==='category-trend'){state.trendCategory=Number(t.value);render();}
  else if(t.dataset.report){state.report[t.dataset.report]=t.value;render();}
});
document.addEventListener('input',event=>{
  const t=event.target;
  if(typeof t.setCustomValidity==='function')t.setCustomValidity('');
  if(t.dataset.input==='unit-search'){const pos=t.selectionStart;state.search=t.value;render();const next=$('[data-input="unit-search"]');next.focus();if(next.type!=='search')next.setSelectionRange(pos,pos);}
  if(t.id==='unit-name'&&!$('form[data-form="unit"]').dataset.id){const target=$('#unit-username');if(target&&!target.dataset.manual)target.value='UBS'+t.value.replace(/^UBS\s*/i,'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9]/g,'');}
  if(t.id==='unit-username')t.dataset.manual='true';
});
document.addEventListener('invalid',event=>{
  const t=event.target;
  if(!t.validity||typeof t.setCustomValidity!=='function')return;
  const v=t.validity;
  if(v.valueMissing)t.setCustomValidity('Preencha este campo para continuar.');
  else if(v.rangeUnderflow||v.rangeOverflow)t.setCustomValidity(`Informe um valor entre ${t.min} e ${t.max}.`);
  else if(v.tooShort)t.setCustomValidity(`Use pelo menos ${t.minLength} caracteres.`);
  else if(v.patternMismatch)t.setCustomValidity('Use apenas letras e números, sem espaços.');
  else if(v.badInput||v.typeMismatch)t.setCustomValidity('Informe um valor válido para este campo.');
},true);
document.addEventListener('submit',async event=>{
  const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const values=Object.fromEntries(new FormData(form)),type=form.dataset.form,submit=$('[type="submit"]',form);if(submit)submit.disabled=true;
  const showError=message=>{const box=$('.form-error',form)||$('#login-error');if(box)box.innerHTML=`<div class="error" role="alert">${escape(message)}</div>`;};
  try {
    if(type==='login'){await post('/api/auth/login',values);await init();return;}
    if(type==='unit-logout'){await post('/api/auth/verify',values);await logout();return;}
    if(type==='dates'){const days=(Date.parse(values.end)-Date.parse(values.start))/86400000+1;if(!Number.isFinite(days)||days<1||days>731)throw Error('Escolha um período de 1 a 731 dias.');state.start=values.start;state.end=values.end;state.preset=0;state.evalPage=1;state.auditPage=1;closeModal();await load();return;}
    if(type==='unit'){if(form.dataset.id)await patch('/api/admin/units/'+form.dataset.id,values);else await post('/api/admin/units',values);toast(form.dataset.id?'Unidade atualizada.':'Unidade e acesso cadastrados.');}
    if(type==='user'){await post('/api/admin/users',values);toast('Acesso criado com sucesso.');}
    if(type==='reset-password'){await patch('/api/admin/users/'+form.dataset.id,values);toast('Senha provisória redefinida.');}
    if(type==='password'){if(values.password!==values.confirm)throw Error('A confirmação não corresponde à nova senha.');await post('/api/auth/password',values);state.user.must_change=false;closeModal();toast('Senha alterada com sucesso.');if(state.user.role==='unit')resetKiosk();else await load();return;}
    if(type==='alert'){await patch('/api/admin/alerts/'+form.dataset.id,values);toast('Revisão registrada.');}
    if(type==='settings'){state.photoRetentionDays=Number(values.photo_retention_days);await patch('/api/admin/settings',Object.fromEntries(Object.entries(values).map(([k,v])=>[k,Number(v)])));toast('Parâmetros salvos.');}
    if(type==='evaluation-search'){state.search=values.q;state.evalPage=1;await load();return;}
    if(type==='staff'){await post('/api/auth/verify',values);modal('Opções do totem',`<p class="form-note">${escape(state.user.unit_name)}</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="button" data-action="password">Alterar senha</button><button class="button danger" data-action="logout">${icon('logout')}Encerrar sessão</button></div>`);return;}
    closeModal();await load();
  }catch(e){showError(e.message);}finally{if(submit?.isConnected)submit.disabled=false;}
});
for(const name of ['pointerdown','keydown'])document.addEventListener(name,()=>{if(state.user?.role==='unit'&&kiosk.step!=='success'){kiosk.lastActive=Date.now();$('#inactivity-warning')?.remove();}},{passive:true});
init();
